    ["M1004", ["2026-10-12T18:23:00"], "푸른마을"],
    ["M1005", ["2026-10-11T09:00:00"], "새싹수학학원"],
  ];
  for (const [id, deadlines, merchant] of latest) {
    const inbox = w.inbox(id);
    eq(inbox.length, deadlines.length, `pushes received by ${id}`);
    inbox.forEach((n, i) => {
